#!/usr/bin/env node
'use strict';
// The 4K packet is generated by the REAL XI scene and real RVPC2 snapshot.
// No mocked vehicle positions, raster inputs or camera geometry.
const assert=require('node:assert/strict');
const fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const cp=require('node:child_process'),crypto=require('node:crypto');
const cli=path.resolve(process.argv[2]||'build/velocity/reverse_pc');
const root=path.resolve('reverse-os-android/app/src/main/assets/velocity');
const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'velocity-4k-capture-'));
function run(...args){const p=cp.spawnSync(cli,args,{encoding:null,timeout:30000,maxBuffer:12*1024*1024});assert.ifError(p.error);assert.equal(p.status,0,String(p.stderr));return p.stdout;}
const header='#!reverse-pc-machine-v1\n';
const sha=buffer=>crypto.createHash('sha256').update(buffer).digest('hex');
try {
 const initial=path.join(tmp,'init.rvp'),world=path.join(tmp,'world.rvp'),ready=path.join(tmp,'ready.rvp');
 run('init',initial);
 run('run',path.join(root,'world.xi'),initial,world);
 const drive=fs.readFileSync(path.join(root,'drive.xi'),'utf8');
 fs.writeFileSync(path.join(tmp,'reset.xi'),
   header+'store8 128 0\nstore8 129 0\nstore8 130 1\nstore8 131 0\nstore8 132 1\n'+drive.slice(header.length));
 run('run',path.join(tmp,'reset.xi'),world,ready);
 const original=sha(fs.readFileSync(ready));
 const gpuSource=fs.readFileSync(path.join(root,'render4k.xi'),'utf8');
 assert(gpuSource.startsWith(header));
 const sample=header+'store8 200 1\nstore8 201 0\nstore8 202 0\n'+gpuSource.slice(header.length);
 const script=path.join(tmp,'capture.xi');fs.writeFileSync(script,sample);
 const first=run('run',script,ready,path.join(tmp,'candidate-a.rvp'));
 const second=run('run',script,ready,path.join(tmp,'candidate-b.rvp'));
 assert(first.equals(second),'GPU geometry packet must be deterministic');
 assert.equal(sha(fs.readFileSync(ready)),original,'4K render mutated the XI race state');
 assert.equal(first.toString('ascii',0,4),'XFG4');
 assert.equal(first.readUInt16LE(4),3840);
 assert.equal(first.readUInt16LE(6),2160);
 assert.equal(first.readUInt32LE(8),4);
 const faces=first.readUInt32LE(12);
 assert(faces>1500&&faces<=8192,'genuine XI geometry faces missing');
 assert.equal(first.length,16+2048+faces*60,'GPU packet bound/stride');
 for(let i=16;i<16+2048;++i)assert(first[i]<=15,'texture atlas exceeds nibble');
 let textured=0,asphalt=0,paint=0,glass=0,depths=0;
 const tiles=new Set(),bases=new Set();
 for(let f=0;f<faces;++f){
  const off=16+2048+f*60;
  for(let i=0;i<3;++i){
   const z=first.readInt32LE(off+i*12+8),shade=first.readUInt16LE(off+48+i*2);
   assert(z>=1&&z<=1000000,'invalid captured camera depth');
   assert(shade<=65280,'invalid 8-bit Q8 shader intensity');
   depths+=z;
  }
  const base=first[off+54],ramp=first[off+55],tile=first[off+56],strength=first[off+57];
  assert(ramp>=1&&base+ramp<=256&&tile<8&&strength<=16,'invalid palette/atlas reference');
  assert.equal(first.readUInt16LE(off+58),0,'GPU wire reserved bits');
  bases.add(base);
  if(strength){textured++;tiles.add(tile);}
  if(base===40)asphalt++;
  if(base===64)paint++;
  if(base===184)glass++;
 }
 console.log('XFG4_CAPTURE_STATS',JSON.stringify({faces,textured,asphalt,paint,glass,tiles:[...tiles]}));
 assert(textured>10,'XI texture-coordinated geometry missing');
 assert(asphalt>0,'4K road is not using original XI asphalt texture');
 assert(paint>0,'4K vehicle not using its paint materials');
 assert(glass>0,'4K canopy not using its tinted glass materials');
 assert(tiles.has(0)&&tiles.has(2)&&tiles.has(5),'paint, glass and asphalt tiles not integrated');
 const result={passed:true,width:3840,height:2160,faces,packetBytes:first.length,
   texturedFaces:textured,asphaltFaces:asphalt,paintFaces:paint,glassFaces:glass,
   tileIds:[...tiles].sort(),paletteBases:[...bases].sort((a,b)=>a-b),
   sha256:sha(first),unchangedRaceSnapshot:true};
 console.log('XI_4K_SCENE_CAPTURE_PASS '+JSON.stringify(result));
 if(process.argv[3])fs.writeFileSync(path.resolve(process.argv[3]),JSON.stringify(result,null,2)+'\n');
}finally{fs.rmSync(tmp,{recursive:true,force:true});}
